6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // invoice references project references client, so drop referential integrity around the
36	        // truncates: RESTART IDENTITY on each, then restore it. Order-independent and clears every
37	        // FK-referenced table.
38	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
39	        jdbc.execute("TRUNCATE TABLE invoice RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
42	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
43	    }
44	
45	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
46	    @SuppressWarnings("unchecked")
